void change(int *p) //交换函数
{
int i,j,temp;
int *pmax,*pmin;
pmax=p;
pmin=p;
for(i=0;i<5;i++) //找最大值和最小值的地址，并赋给pmax，pmin
for(j=i;j<5;j++)
{
if(*pmax<*(p+5*i+j))
pmax=p+5*i+j;
if(*pmin>*(p+5*i+j))
pmin=p+5*i+j;
}
temp=*(p+12); //将最大值换给中心元素
