认为单词是全由字母组成的字符串，程序中设longest函数的作用是找最长单词的位置。此函数的返回值是该行字符中最长单词的起始位置。flag表示单词是否已开始，flag＝0表示未开始，flag＝1表示单词开始；len代表当前单词已累计的字母个数；length代表先前单词中最长单词的长度；point代表当前单词的起始位置（用下标表示）；place代表最长单词的起始位置。函数alphabetic的作用是判断当前字符是否字母，若是则返回1，否则返回0。
程序如下：
#include<stdio.h>
#include<string.h>
int main()
{
int alphabetic(char);
int longest(char []);
int i;
char line[100];
printf("input one line:
");
gets(line);
printf("The longest word is:");
for(i=longest(line);alphabetic(line[i    ]);i++)
printf("%c",line[i]);
printf("
");
return 0;
}
int alphabetic(char c) //判断是否为字母
{
if((c>='a'&&c<='z')||(c>='A'&&c<='Z'))
return(1);
else
return(0);
}
int longest(char string[]) //查找最长的单词
{
int len=0,i,length=0,flag=1,place=0,point;
for(i=0;i<=strlen(string);i++)
if(alphabetic(string[i])) //当前字符是字母
if(flag) //若flag=1，表明该字符为一个单词的开始
{
point=i; //记录单词的起始点
flag=0;
len++;
}
else //若flag不为1，表明该字符为一个单词的非首部
len++;
else //当前字符不是字母时，表示一个单词结束，计算该单词的长度
{
flag=1;
if(len>=length) //若该单词比上一个最长的单词还要长，记录下来
{
length=len;
place=point;
}
len=0;
}
return(place);
}
